create or replace function public.get_import_rows_review(p_import_id uuid,p_limit integer default 100,p_offset integer default 0,p_search text default null,p_validation_status text default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_org uuid;v_total bigint;v_limit integer:=least(greatest(coalesce(p_limit,100),1),500);v_offset integer:=greatest(coalesce(p_offset,0),0);v_items jsonb;begin select organization_id into v_org from public.imports where id=p_import_id;if v_org is null then raise exception 'IMPORT_NOT_FOUND';end if;if not public.has_org_permission(v_org,'import.view') then raise exception 'IMPORT_VIEW_PERMISSION_REQUIRED';end if;select count(*) into v_total from public.import_rows r where r.import_id=p_import_id and (p_validation_status is null or p_validation_status='' or r.validation_status=p_validation_status) and (p_search is null or btrim(p_search)='' or r.row_number::text ilike '%'||btrim(p_search)||'%' or coalesce(r.source_key,'') ilike '%'||btrim(p_search)||'%' or r.payload::text ilike '%'||btrim(p_search)||'%');select coalesce(jsonb_agg(to_jsonb(x) order by x.row_number),'[]'::jsonb) into v_items from (select r.id,r.row_number,r.source_key,r.payload,r.validation_status,r.validation_message from public.import_rows r where r.import_id=p_import_id and (p_validation_status is null or p_validation_status='' or r.validation_status=p_validation_status) and (p_search is null or btrim(p_search)='' or r.row_number::text ilike '%'||btrim(p_search)||'%' or coalesce(r.source_key,'') ilike '%'||btrim(p_search)||'%' or r.payload::text ilike '%'||btrim(p_search)||'%') order by r.row_number limit v_limit offset v_offset)x;return jsonb_build_object('total',v_total,'limit',v_limit,'offset',v_offset,'items',v_items);end;$$; revoke all on function public.get_import_rows_review(uuid,integer,integer,text,text) from public,anon; grant execute on function public.get_import_rows_review(uuid,integer,integer,text,text) to authenticated;